<script setup lang="ts">
// Generated by FormsGen — no runtime dependencies beyond Vue.
import { nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'

const emit = defineEmits<{ submit: [data: Record<string, unknown>] }>()

type FormData = {
  first_name: string
  last_name: string
  email: string
  phone: string
  ticket: string | null
  seats: number | null
  diet: string | null
  diet_other: string
  workshops: string[]
  arrival: string
  notes: string
  terms: boolean
}

const form = reactive<FormData>({
  first_name: "",
  last_name: "",
  email: "",
  phone: "",
  ticket: null,
  seats: null,
  diet: null,
  diet_other: "",
  workshops: [],
  arrival: "",
  notes: "",
  terms: false
