  if (fgIsBlank(v)) return "This field is required"
  if (!fgIsEmpty(v) && ((fgSize(v) ?? -Infinity) < 2)) return "Must be at least 2"
  return null
  },
  'last_name': function () {
  const v = form.last_name
  if (fgIsBlank(v)) return "This field is required"
  return null
  },
  'email': function () {
  const v = form.email
  if (fgIsBlank(v)) return "This field is required"
  if (!fgIsEmpty(v) && ((typeof v !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)))) return "Must be a valid email address"
  return null
  },
  'ticket': function () {
  const v = form.ticket
  if (fgIsBlank(v)) return "This field is required"
  return null
  },
  'seats': function () {
  const v = form.seats
  if (fgIsBlank(v)) return "This field is required"
  if (!fgIsEmpty(v) && ((fgSize(v) ?? -Infinity) < 1)) return "Must be at least 1"
  if (!fgIsEmpty(v) && ((fgSize(v) ?? Infinity) > 5)) return "Must be at most 5"
  return null
  },
  'diet_other': function () {
  if (!fgVisible_diet_other()) return null
  const v = form.diet_other
  if (fgIsBlank(v)) return "This field is required"
  return null
